,p_plugin_id=>wwv_flow_imp.id(1075232931295249171)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>9
,p_display_sequence=>90
,p_prompt=>'Show Icon Labels'
,p_attribute_type=>'SELECT LIST'
,p_is_required=>false
,p_default_value=>'DEFAULT'
,p_supported_component_types=>'APEX_APPLICATION_PAGE_ITEMS:APEX_APPL_PAGE_IG_COLUMNS'
,p_is_translatable=>false
,p_lov_type=>'STATIC'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'Override the application wide <strong>Show Icon Labels</strong> setting for this item only.',
'<br><br>',
'<strong>Use application default</strong> - follow whatever is set under Shared ',
'Components, Plug-ins, IconPicker. This is the default.<br>',
'<strong>Yes</strong> / <strong>No</strong> - ignore the application setting for this ',
'item.<br><br>',
'The plug-in ships with the application default set to <strong>No</strong>.',
'<br><br>',
'When on, the icon class name is printed under each icon, for example ',
'<strong>fa-user</strong>.'))
);
