wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(28038196300346046558)
,p_process_sequence=>10
,p_process_point=>'AFTER_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Load collection'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'	l_coll_name varchar2(30) := ''IP_COLLECTION'';',
'',
'begin',
'',
'	APEX_COLLECTION.CREATE_OR_TRUNCATE_COLLECTION(l_coll_name);',
'',
'	APEX_COLLECTION.ADD_MEMBER (p_collection_name => l_coll_name, ',
'								p_c001 => ''fa-user'',',
'								p_c002 => ''fa-close'',',
'								p_c003 => '''',',
'								p_c004 => '''',',
'								p_c005 => ''''',
'								);',
'								',
'	APEX_COLLECTION.ADD_MEMBER (p_collection_name => l_coll_name, ',
'								p_c001 => '''',',
'								p_c002 => ''fa-print'',',
'								p_c003 => '''',',
'								p_c004 => '''',',
'								p_c005 => ''''',
'								);',
'								',
'	APEX_COLLECTION.ADD_MEMBER (p_collection_name => l_coll_name, ',
'								p_c001 => ''fa-comment'',',
'								p_c002 => '''',',
'								p_c003 => '''',',
'								p_c004 => ''fa-save'',',
'								p_c005 => ''''',
'								);		',
'',
'	APEX_COLLECTION.ADD_MEMBER (p_collection_name => l_coll_name, ',
'								p_c001 => '''',',
'								p_c002 => ''fa-universal-access'',',
'								p_c003 => '''',',
'								p_c004 => '''',',
'								p_c005 => ''''',
'								);			',
