'                    p_seq => :SEQ_ID,',
'                    p_c001 => :ICON,',
'                    p_c002 => :ICON_ONLY,',
'                    p_c003 => :ICON_RO,',
'                    p_c004 => :ICON_ONLY_RO,',
'                    p_c005 => :READ_ONLY);',
'    when ''D'' then',
'       APEX_COLLECTION.DELETE_MEMBER (',
'            p_collection_name => l_coll_name,',
'            p_seq => :SEQ_ID);',
'    end case;',
'end;'))
